import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';

import { loadExecutionModel } from './plan-model.mjs';

const OUTPUT_PATH = path.join('docs', 'execution', 'PHASE_PROMPTS.md');

export function renderPhasePrompts(model) {
  const blocks = model.packets.map(renderPacket);
  return `# Ready-to-Copy Phase Conversation Prompts

<!-- Generated by scripts/execution/generate-phase-prompts.mjs. Do not edit by hand. -->

**Status:** Generated execution aid
**Owner:** Product and Engineering

Use exactly one prompt per new conversation. Generated blocks bind only a phase
packet, its dependency capability gate, outcome, and stopping boundary; each
block references the single complete mandatory workflow.

${blocks.join('\n\n')}
`;
}

export async function renderFormattedPhasePrompts(model) {
  return prettier.format(renderPhasePrompts(model), { filepath: OUTPUT_PATH });
}

function renderPacket(packet) {
  const dependencySummary =
    packet.dependsOn.length === 0
      ? 'None. This is the root phase.'
      : packet.dependencyGate
          .map(
            (row) =>
              `${row.dependency} at ${row.minimumLifecycle}: ${row.requiredCapability} ` +
              `(evidence: ${row.requiredEvidence}).`,
          )
          .join('\n');

  return `## ${packet.id} — ${packet.title}

Copy this entire block into one new conversation:

\`\`\`text
Execute exactly phase ${packet.id} from:
${packet.path}

Required outcome:
${packet.outcome}

Dependency capability gate:
${dependencySummary}

Follow the complete mandatory workflow in docs/execution/AGENT_PROMPT.md.

Conversation boundary:
${packet.boundary}
\`\`\``;
}

export async function writePhasePrompts(rootDir, model) {
  const resolvedModel = model ?? (await loadExecutionModel(rootDir));
  await writeFile(
    path.join(rootDir, OUTPUT_PATH),
    await renderFormattedPhasePrompts(resolvedModel),
    'utf8',
  );
}

export async function checkPhasePrompts(rootDir, model) {
  const resolvedModel = model ?? (await loadExecutionModel(rootDir));
  try {
    const current = await readFile(path.join(rootDir, OUTPUT_PATH), 'utf8');
    return current === (await renderFormattedPhasePrompts(resolvedModel));
  } catch {
    return false;
  }
}

async function main() {
  const rootDir = process.cwd();
  if (process.argv.includes('--check')) {
    if (!(await checkPhasePrompts(rootDir))) {
      console.error('PHASE_PROMPTS.md is stale; run pnpm execution:generate');
      process.exitCode = 1;
    }
    return;
  }
  await writePhasePrompts(rootDir);
}

const isCli = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isCli) await main();
